def yavas(liste, sorgular):
    # her sorgu icin listeyi bastan tara
    sonuc = 0
    for s in sorgular:
        for x in liste:
            if x == s:
                sonuc += 1
                break
    return sonuc

def hizli(liste, sorgular):
    # tek seferlik kume kurulumu, sonra O(1) arama
    kume = set(liste)
    return sum(1 for s in sorgular if s in kume)

veri = list(range(10000))
sorgu = [9999, 5000, 123456]
print(yavas(veri, sorgu), hizli(veri, sorgu))
